import random

GROUP = "number_theory"
SKILL = "induction"


def find_max_exponent(n, min_exp, max_exp):
    if n == 0:
        return 0

    if n < min_exp:
        return -1

    max_count = 0

    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_exp = rng.randint(3, 10)
    max_exp = rng.randint(20, 40)
    n = rng.randint(50, 100)

    answer = find_max_exponent(n, min_exp, max_exp)

    check = -1
    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of distinct powers of 2 where the exponent ranges from {min_exp} to {max_exp} (inclusive). "
        f"What is the maximum number of distinct powers of 2 that can be selected such that no exponent exceeds the total {n} and all selected exponents sum to exactly {n}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "number_theory"
SKILL = "construction"


def count_combinations(target, min_digit):
    total_ways = 0

    for combination in range(min_digit, target + 1):
        if combination <= target:
            ways = calculate_ways(combination, target)
            total_ways += ways

    return total_ways

def calculate_ways(combination, target):
    if combination == 0 and target == 0:
        return 1
    if combination == 0 or target < 0:
        return 0
    return calculate_ways(combination - 1, target - combination) + calculate_ways(combination, target - (combination + 1))

def find_threshold(min_digit, max_digit):
    for threshold_count in range(min_digit, max_digit + 1):
        if count_combinations(threshold_count, min_digit) > 0:
            return threshold_count
    return max_digit

def generate(seed):
    rng = random.Random(seed)

    min_digit = rng.randint(1, 5)
    max_digit = rng.randint(10, 20)

    threshold_count = find_threshold(min_digit, max_digit)

    check_threshold_count = min_digit
    while check_threshold_count <= max_digit:
        if count_combinations(check_threshold_count, min_digit) == 0:
            check_threshold_count += 1
        else:
            break

    assert threshold_count == check_threshold_count, f"threshold_count={threshold_count} check_threshold_count={check_threshold_count}"

    problem = (
        f"Find the smallest number of digits from {min_digit} to {max_digit} (inclusive) such that there exists a subset of {threshold_count} digits from this range where each digit in the subset is between {min_digit} and {threshold_count} (inclusive), and the sum of these digits equals {threshold_count}. State only the integer."
    )
    return problem, str(threshold_count)

