def find_max_subsets(n, min_subset_sum, max_subset_sum, target_value):
    if n == 0:
        return 0

    if n < min_subset_sum:
        return -1

    max_count = 0

    for subset_sum in range(min_subset_sum, max_subset_sum + 1):
        if subset_sum <= n:
            remaining_n = n - subset_sum
            count = find_max_subsets(remaining_n, min_subset_sum, subset_sum - 1, target_value)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    n = rng.randint(10, 50)
    min_subset_sum = rng.randint(3, 10)
    max_subset_sum = rng.randint(15, 30)
    target_value = rng.randint(30, 60)

    answer = find_max_subsets(n, min_subset_sum, max_subset_sum, target_value)

    check = -1
    for subset_sum in range(min_subset_sum, max_subset_sum + 1):
        if subset_sum <= n:
            remaining_n = n - subset_sum
            count = find_max_subsets(remaining_n, min_subset_sum, subset_sum - 1, target_value)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of integers ranging from 1 to {n}. What is the maximum number of distinct subsets that can be selected such that the sum of any subset ranges from {min_subset_sum} to {max_subset_sum} (inclusive), no subset sum exceeds the target divisor sum {target_value}, and all subset sums sum to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)

