def find_max_points(target, min_distance_sum, max_distance_sum, num_points):
    if target == 0:
        return 0

    if target < min_distance_sum:
        return -1

    max_count = 0

    for distance_sum in range(min_distance_sum, max_distance_sum + 1):
        if distance_sum <= target:
            remaining_target = target - distance_sum
            count = find_max_points(remaining_target, min_distance_sum, distance_sum - 1, num_points - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_distance_sum = rng.randint(5, 15)
    max_distance_sum = rng.randint(25, 40)
    target_distance = rng.randint(20, 50)
    num_points = rng.randint(5, 10)

    answer = find_max_points(target_distance, min_distance_sum, max_distance_sum, num_points)

    check = -1
    for distance_sum in range(min_distance_sum, max_distance_sum + 1):
        if distance_sum <= target_distance:
            remaining_target = target_distance - distance_sum
            count = find_max_points(remaining_target, min_distance_sum, distance_sum - 1, num_points - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"A circle is divided into distinct points. The sum of the distances between any subset of points ranges from {min_distance_sum} to {max_distance_sum} (inclusive). "
        f"What is the maximum number of distinct points that can be selected such that no subset sum of distances exceeds the target sum {target_distance} and all subset sums sum to exactly {target_distance}? State only the integer."
    )
    return problem, str(answer)
